          changed ||= cleanedPart !== part;
          return cleanedPart;
        }

        if (part && typeof part.text === 'string') {
          const cleanedText = consumePrefillThinkingText(part.text);
          if (cleanedText !== part.text) {
            changed = true;
            return { ...part, text: cleanedText };
          }
        }

